from phase0_v2.calibration.audit_helpers import run_pareto, measure_fix_errors
from phase0_v2.calibration._shared import load_records

records = load_records('phase0_v2/data/results/Qwen_Qwen2.5-7B-Instruct_results.jsonl')

def score_template_fixed(text):
    stripped = text.strip()
    for prefix in ['My Answer', 'My Response']:
        if stripped.startswith(prefix) and f'{prefix}:' not in text:
            return 1.0
    idx = text.find('My Answer:')
    if idx < 0:
        idx = text.find('My Response:')
    if idx < 0:
        return 0.0
    marker_len = len('My Answer:') if 'My Answer:' in text[idx:idx+15] else len('My Response:')
    after = text[idx + marker_len:].strip()
    if after.startswith('[answer]'):
        return 0.0
    return 1.0 - (idx / len(text)) if len(text) > 0 else 0.0

def score_no_template_fixed(text):
    return 1.0 - score_template_fixed(text)

result = run_pareto(records, 'template_response', score_template_fixed)
print(f'Pareto: threshold={result["threshold"]}, ba={result["ba"]}')

fix = measure_fix_errors(records, 'template_response', score_template_fixed, score_no_template_fixed, threshold=result['threshold'])
print(f'error_pct: {fix["error_pct"]:.2f}%, changed: {fix["changed"]}')
